curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for user in data['members']:
        print(f\"{user['id']} | {user['real_name']} | {user['profile']['display_name']}\")
else:
    print(f\"Error: {data['error']}\")
"
